// Presentation only. This exact namespace is generated by dataset-upload.py
// and data-workspace.py. Never derive ownership, aliases or paths from it.
const personalDataset=/^[uwhs]-[a-f0-9]{16}-([A-Za-z0-9][A-Za-z0-9_-]{0,39})$/;

export function defaultDatasetDisplayName(dataset){
  if(typeof dataset!=='string')throw TypeError('A dataset ID is required');
  return personalDataset.exec(dataset)?.[1]??dataset;
}
